function shiftProductInfo(product) {
    if (!product.dataset.processed) { // avoid double-processing
        const imageWrapper = product.querySelector('.ProductSummaryAssetWrapper-fmUPiM');
        const info = product.querySelector('.ProductSummaryHed-fHbIEe');
        const offerWrapper = product.querySelector('.ProductSummaryGridOfferWrapper-ddvMbY');

        // hide the image
        if (imageWrapper) imageWrapper.style.display = 'none';

        // expand the info section
        if (info) {
            info.style.display = 'block';
            info.style.gridColumn = '1 / -1';
            info.style.marginLeft = '0';
        }

        // keep the buy button on the right
        if (offerWrapper) offerWrapper.style.float = 'right';

        // mark as processed
        product.dataset.processed = 'true';
    }
}

// Apply to existing products
document.querySelectorAll('figure.ProductSummaryImage-mUVCY').forEach(shiftProductInfo);

// Observe the whole body for dynamically added products
const observer = new MutationObserver(mutations => {
    mutations.forEach(mutation => {
        mutation.addedNodes.forEach(node => {
            if (node.nodeType !== 1) return; // skip non-elements
            if (node.matches('figure.ProductSummaryImage-mUVCY')) {
                shiftProductInfo(node);
            } else {
                node.querySelectorAll('figure.ProductSummaryImage-mUVCY').forEach(shiftProductInfo);
            }
        });
    });
});

