  function addTopPick(card) {
    if (card.dataset.gbTopPickAdded) return;
    card.dataset.gbTopPickAdded = "true";

    // Add border around the card
    card.style.border = "3px solid #007BFF"; // blue border
    card.style.borderRadius = "0"; // square corners
    card.style.position = "relative"; // for badge positioning
    card.style.overflow = "visible"; // badge can straddle edges

    // Create badge element
    const badge = document.createElement("div");
    badge.textContent = "TOP PICK";

    // Style the badge
    badge.style.position = "absolute";
    badge.style.left = "10px"; // slightly inset from left edge
    badge.style.top = "0"; // top of card
    badge.style.transform = "translateY(-50%)"; // vertically center on top border
    badge.style.backgroundColor = "#007BFF"; // blue badge
    badge.style.color = "#FFFFFF";
    badge.style.padding = "3px 16px"; // slightly shorter, wider
    badge.style.fontFamily = "WiredMono, helvetica, sans-serif"; // desired font
    badge.style.fontWeight = "bold";
    badge.style.fontSize = "14px"; // increased font size
    badge.style.borderRadius = "12px"; // pill shape
    badge.style.boxShadow = "0 2px 6px rgba(0,0,0,0.15)";
    badge.style.zIndex = "10"; // make sure it's above the border

    card.appendChild(badge);
  }

  // Robust detection for any product card (desktop or mobile)
  function findProductCards() {
    return Array.from(document.querySelectorAll('[class*="ProductCardWrapper"], [class*="UnifiedLandscapeProductCardWrapper"]'));
  }

  // Observer callback
  function checkAndAddBadges() {
    const cards = findProductCards();
    if (cards.length > 0) {
      // Only add to the first card
      addTopPick(cards[0]);
      return true;
    }
    return false;
  }

  // MutationObserver to watch for dynamic page changes
  const observer = new MutationObserver(() => {
    checkAndAddBadges();
  });

  observer.observe(document.body, { childList: true, subtree: true });

  // Also check immediately in case card already exists
  checkAndAddBadges();
})();
