    badge.style.fontWeight = "bold";
    badge.style.fontSize = "14px"; // increased font size
    badge.style.borderRadius = "12px"; // pill shape
    badge.style.boxShadow = "0 2px 6px rgba(0,0,0,0.15)";
    badge.style.zIndex = "10"; // make sure it's above the border

    card.appendChild(badge);
  }

  // Robust detection for any product card (desktop or mobile)
  function findProductCards() {
    return Array.from(document.querySelectorAll('[class*="ProductCardWrapper"], [class*="UnifiedLandscapeProductCardWrapper"]'));
  }

  // Observer callback
  function checkAndAddBadges() {
    const cards = findProductCards();
    if (cards.length > 0) {
      // Only add to the first card
      addTopPick(cards[0]);
      return true;
    }
    return false;
  }

  // MutationObserver to watch for dynamic page changes
  const observer = new MutationObserver(() => {
    checkAndAddBadges();
  });

  observer.observe(document.body, { childList: true, subtree: true });

  // Also check immediately in case card already exists
  checkAndAddBadges();
})();
