  function addTopPick(card) {
    if (card.dataset.gbTopPickAdded) return;
    card.dataset.gbTopPickAdded = "true";

    // Add border around the card
    card.style.border = "3px solid #007BFF"; // blue border
    card.style.borderRadius = "0"; // square corners
    card.style.position = "relative"; // for badge positioning
    card.style.overflow = "visible"; // badge can straddle edges

    // Create badge element
    const badge = document.createElement("div");
    badge.textContent = "TOP PICK";

    // Style the badge
    badge.style.position = "absolute";
    badge.style.left = "10px"; // slightly inset from left edge
    badge.style.top = "0"; // top of card
    badge.style.transform = "translateY(-50%)"; // vertically center on top border
    badge.style.backgroundColor = "#007BFF"; // blue badge
    badge.style.color = "#FFFFFF";
